/** Statuses whose entry stamps `completed_at`; leaving one clears it again. */
const TERMINAL_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

type IssueLookup = (issueId: IssueId) => Issue | null;

/** Synchronous reads let a service validate a hierarchy inside a write transaction. */
function scopedIssueLookup(orgId: OrgId): IssueLookup {
  return (issueId) => {
    const row = getDb().select().from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();
    return row ? toIssue(row) : null;
  };
}

/** Include archived links while walking; filtering happens at the leaves. */
function subtreeIds(orgId: OrgId, projectId: ProjectId, issueId: IssueId): SQL {
  return sql`(
    with recursive issue_tree(id) as (
      select ${issues.id} from ${issues}
      where ${orgPredicate(issues.orgId, orgId)}
        and ${eq(issues.projectId, projectId)} and ${eq(issues.id, issueId)}
      union
      select ${issues.id} from ${issues}
      inner join issue_tree on ${issues.parentId} = issue_tree.id
      where ${orgPredicate(issues.orgId, orgId)}
        and ${eq(issues.projectId, projectId)}
    ) select id from issue_tree
  )`;
}

function readIssueRollup(
  orgId: OrgId,
  projectId: ProjectId,
  issueId: IssueId,
): IssueRollup {
  const row = getDb()
    .select({
      total: count(),
      closed: sql<number>`coalesce(sum(case when ${inArray(issues.status, [...CLOSED_ISSUE_STATUSES])} then 1 else 0 end), 0)`,
    })
    .from(issues)
    .where(and(
      orgPredicate(issues.orgId, orgId),
      eq(issues.projectId, projectId),
      ne(issues.id, issueId),
      inArray(issues.id, subtreeIds(orgId, projectId, issueId)),
      livePredicate(issues.archivedAt, {}),
    ))
    .get();
  const total = row?.total ?? 0;
  const closed = row?.closed ?? 0;
  return { total, open: total - closed, closed };
}

export async function getIssueRollup(
  orgId: OrgId,
  projectId: ProjectId,
  issueId: IssueId,
): Promise<IssueRollup> {
  return readIssueRollup(orgId, projectId, issueId);
}

export async function listSubIssues(
  orgId: OrgId,
  projectId: ProjectId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb().select().from(issues)
    .where(and(
      orgPredicate(issues.orgId, orgId),
      eq(issues.projectId, projectId),
      eq(issues.parentId, issueId),
      livePredicate(issues.archivedAt, {}),
    ))
    .orderBy(asc(issues.createdAt), asc(issues.number))
    .all();
  const labels = await listLabelsForIssues(orgId, rows.map((row) => row.id as IssueId));
  return rows.map((row) => toIssue(row, (labels[row.id] ?? []).map((label) => label.id)));
}

/** Unpaginated and including archived descendants, for structural checks. */
export async function listIssueDescendants(
  orgId: OrgId,
  projectId: ProjectId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  return readIssueDescendants(orgId, projectId, issueId);
}

function readIssueDescendants(
  orgId: OrgId,
  projectId: ProjectId,
  issueId: IssueId,
): readonly Issue[] {
  return getDb().select().from(issues)
    .where(and(
      orgPredicate(issues.orgId, orgId),
      eq(issues.projectId, projectId),
      ne(issues.id, issueId),
      inArray(issues.id, subtreeIds(orgId, projectId, issueId)),
    ))
    .all()
    .map((row) => toIssue(row));
}

/** Called only after a live, open child closes, in the mutation transaction. */
function completedParentFor(child: IssueRow): Issue | null {
  if (child.parentId === null) return null;
  const parent = getDb().select().from(issues)
    .where(and(
      orgPredicate(issues.orgId, child.orgId as OrgId),
      eq(issues.projectId, child.projectId),
      eq(issues.id, child.parentId),
      livePredicate(issues.archivedAt, {}),
      isNotNull(issues.assigneeId),
    ))
    .get();
  if (!parent) return null;
  const rollup = readIssueRollup(
    parent.orgId as OrgId, parent.projectId as ProjectId, parent.id as IssueId,
  );
  return rollup.open === 0 ? toIssue(parent) : null;
}

