export async function insertIssue(
  input: CreateIssueInput,
  authorId: UserId,
  issueNumber: number,
  validateParent?: (findIssue: IssueLookup) => void,
): Promise<Issue> {
  return getDb().transaction((db) => {
    validateParent?.(scopedIssueLookup(input.orgId));
    const stamp = toIsoTimestamp(new Date());

  const row = db
    .insert(issues)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      number: issueNumber,
      title: input.title,
      description: input.description,
      status: input.status,
      priority: input.priority,
      authorId,
      assigneeId: input.assigneeId,
      parentId: input.parentId,
      estimate: input.estimate,
      dueAt: input.dueAt,
      startedAt: null,
      completedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  if (input.labelIds.length > 0) {
    db.insert(issueLabels)
      .values(
        input.labelIds.map((labelId) => ({
          orgId: input.orgId,
          issueId: row.id,
          labelId,
        })),
      )
      .run();
  }

    return toIssue(row, input.labelIds);
  });
}

export async function updateIssue(input: UpdateIssueInput): Promise<Issue> {
  const db = getDb();
  const row = db
    .update(issues)
    .set({
      ...(input.title === undefined ? {} : { title: input.title }),
      ...(input.description === undefined
        ? {}
        : { description: input.description }),
      ...(input.priority === undefined ? {} : { priority: input.priority }),
      ...(input.estimate === undefined ? {} : { estimate: input.estimate }),
      ...(input.dueAt === undefined ? {} : { dueAt: input.dueAt }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(issues.orgId, input.orgId),
        eq(issues.id, input.issueId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${input.issueId} not found`);

  if (input.labelIds !== undefined) {
    db.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, input.orgId),
          eq(issueLabels.issueId, input.issueId),
        ),
      )
      .run();
    if (input.labelIds.length > 0) {
      db.insert(issueLabels)
        .values(
          input.labelIds.map((labelId: LabelId) => ({
            orgId: input.orgId,
            issueId: input.issueId,
            labelId,
          })),
        )
        .run();
    }
  }

  const labels = await listLabelsForIssues(input.orgId, [input.issueId]);
  return toIssue(row, (labels[input.issueId] ?? []).map((label) => label.id));
}

/** Status transitions maintain `started_at` / `completed_at` bookkeeping. */
export async function setIssueStatus(
  orgId: OrgId,
  issueId: IssueId,
  status: IssueStatus,
): Promise<Issue> {
  return (await setIssueStatusWithCompletion(orgId, issueId, status)).issue;
}

/** Observe completion with the write, so simultaneous closes notify once. */
export async function setIssueStatusWithCompletion(
  orgId: OrgId,
  issueId: IssueId,
  status: IssueStatus,
): Promise<{ issue: Issue; completedParent: Issue | null }> {
  return getDb().transaction((db) => {
    const stamp = toIsoTimestamp(new Date());
    const current = db.select().from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();
    if (!current) throw new Error(`Issue ${issueId} not found`);

    const row = db.update(issues)
      .set({
        status,
        startedAt:
          status === "in_progress" && current.startedAt === null
            ? stamp
            : current.startedAt,
        completedAt: TERMINAL_STATUSES.includes(status) ? stamp : null,
        updatedAt: stamp,
      })
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .returning()
      .get();

    const closing = current.archivedAt === null &&
      !CLOSED_ISSUE_STATUSES.includes(current.status) &&
      CLOSED_ISSUE_STATUSES.includes(status);
    return {
      issue: toIssue(row),
      completedParent: closing ? completedParentFor(current) : null,
    };
  });
}

export async function setIssueParent(
  input: SetIssueParentInput,
  validate?: (current: Issue | null, findIssue: IssueLookup, descendants: readonly Issue[]) => void,
): Promise<Issue> {
  const row = getDb().transaction((db) => {
    const current = db.select().from(issues)
      .where(and(orgPredicate(issues.orgId, input.orgId), eq(issues.id, input.issueId)))
      .get();
    validate?.(
      current ? toIssue(current) : null,
      scopedIssueLookup(input.orgId),
      current ? readIssueDescendants(input.orgId, current.projectId as ProjectId, input.issueId) : [],
    );
    if (!current) throw new Error(`Issue ${input.issueId} not found`);
    if (current.parentId === input.parentId) return current;
    return db.update(issues)
      .set({ parentId: input.parentId, updatedAt: toIsoTimestamp(new Date()) })
      .where(and(
        orgPredicate(issues.orgId, input.orgId),
        eq(issues.id, input.issueId),
      ))
      .returning()
      .get();
  });
  const labels = await listLabelsForIssues(input.orgId, [input.issueId]);
  return toIssue(row, (labels[row.id] ?? []).map((label) => label.id));
}

