/** Archive the complete live subtree before publishing any archive events. */
export async function archiveIssueTree(
  orgId: OrgId,
  projectId: ProjectId,
  issueId: IssueId,
): Promise<{ archivedIssues: readonly Issue[]; completedParent: Issue | null }> {
  return getDb().transaction((db) => {
    const rows = db.update(issues)
      .set(archivePatch())
      .where(and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        inArray(issues.id, subtreeIds(orgId, projectId, issueId)),
        livePredicate(issues.archivedAt, {}),
      ))
      .returning()
      .all();
    const root = rows.find((row) => row.id === issueId);
    return {
      archivedIssues: rows.map((row) => toIssue(row)),
      completedParent: root && !CLOSED_ISSUE_STATUSES.includes(root.status)
        ? completedParentFor(root)
        : null,
    };
  });
}

