/** Count the proposed ancestors, checking the entire chain for a cycle. */
function parentDepth(
  projectId: ProjectId,
  parentId: IssueId,
  findIssue: (issueId: IssueId) => Issue | null,
  issueId?: IssueId,
): number {
  const seen = new Set<IssueId>();
  let nextId: IssueId | null = parentId;
  let depth = 0;

  while (nextId !== null) {
    const found = findIssue(nextId);
    const parent: Issue = requireFound(
      found?.projectId === projectId ? found : null,
      "Issue",
      nextId,
    );
    if (depth === 0) assertNotArchived("Issue", parent.id, parent);
    if (parent.id === issueId || seen.has(parent.id)) {
      throw new IssueHierarchyError(issueId ?? parentId, "cycle");
    }
    seen.add(parent.id);
    depth += 1;
    nextId = parent.parentId;
  }

  return depth;
}

/** Archived descendants still move with their parent and occupy a level. */
function subtreeHeight(issueId: IssueId, descendants: readonly Issue[]): number {
  const children = new Map<IssueId, IssueId[]>();
  for (const issue of descendants) {
    if (issue.parentId === null) continue;
    const siblings = children.get(issue.parentId) ?? [];
    siblings.push(issue.id);
    children.set(issue.parentId, siblings);
  }
  const queue = [{ id: issueId, depth: 0 }];
  let height = 0;
  for (let i = 0; i < queue.length; i += 1) {
    const current = queue[i];
    height = Math.max(height, current.depth);
    for (const id of children.get(current.id) ?? []) {
      queue.push({ id, depth: current.depth + 1 });
    }
  }
  return height;
}

async function announceSubIssuesCompleted(actor: Actor, parent: Issue | null): Promise<void> {
  if (parent?.assigneeId == null) return;
  await emit("issue.sub_issues_completed", {
    ...actorEnvelope(actor),
    issueId: parent.id,
    projectId: parent.projectId,
    assigneeId: parent.assigneeId,
  });
}

/**
 * Creates an issue after checking tenant scope, the `issue:create`
 * permission, a live project, the quota and the proposed parent hierarchy.
 * Only then is a number allocated and `issue.created` published — everything
 * reactive (notifications, search, webhooks, the audit log) hangs off that.
 */
export async function createIssue(
  actor: Actor,
  input: CreateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
  const issue = await issueRepo.insertIssue(input, actor.userId, number, (findIssue) => {
    if (input.parentId === null) return;
    const depth = parentDepth(input.projectId, input.parentId, findIssue);
    if (depth > MAX_SUB_ISSUE_DEPTH) {
      throw new IssueHierarchyError(input.parentId, "too_deep");
    }
  });

  await emit("issue.created", {
    ...actorEnvelope(actor),
    issueId: issue.id,
    projectId: issue.projectId,
    title: issue.title,
    assigneeId: issue.assigneeId,
    priority: issue.priority,
  });

  return issue;
}

export async function updateIssue(
  actor: Actor,
  input: UpdateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const after = await issueRepo.updateIssue(input);

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: Object.keys(input).filter(
      (key) => key !== "orgId" && key !== "issueId",
    ),
  });

  return after;
}

export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);
  let changed = false;
  const after = await issueRepo.setIssueParent(input, (current, findIssue, descendants) => {
    const before = requireFound(current, "Issue", input.issueId);
    assertCan(actor, "issue:update", issueResource(before));
    assertNotArchived("Issue", before.id, before);
    const depth = input.parentId === null ? 0 : parentDepth(
      before.projectId, input.parentId, findIssue, before.id,
    );
    if (depth + subtreeHeight(before.id, descendants) > MAX_SUB_ISSUE_DEPTH) {
      throw new IssueHierarchyError(before.id, "too_deep");
    }
    changed = before.parentId !== input.parentId;
  });
  if (!changed) return after;
  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });
  return after;
}

